cat << 'EOF' > ui/src/features/workflow-composer/utils/mapper.ts
import type { Edge, Node } from "@xyflow/react";
import type { Hook, EventSource } from "../../hooks-view/types";

const X_SPACING = 300;
const Y_SPACING = 150;

function getEvents(hook: Hook): EventSource[] {
	if (hook.events && hook.events.length > 0) {
		return hook.events;
	}
	if (hook.trigger) {
		return [
			{
				type: "agent-operation" as const,
				agent: hook.trigger.agent,
				operation: hook.trigger.operation,
				timing: hook.trigger.timing,
			},
		];
	}
	return [];
}

function processHook(hook: Hook, hookIndex: number, nodes: Node[], edges: Edge[]) {
	const startY = hookIndex * Y_SPACING * 3;
	let currentX = 100;
	const previousNodeIds: string[] = [];

	const eventIds: string[] = [];
	const events = getEvents(hook);

	for (const [i, event] of events.entries()) {
		const id = `hook-${hook.id}-event-${i}`;
		eventIds.push(id);
		nodes.push({
			id,
			type: "source",
			position: { x: currentX, y: startY + i * Y_SPACING },
			data: {
				label: event.type === "agent-operation" ? `${event.agent} ${event.operation}` : event.type,
				description: `Event source for ${hook.name}`,
				hookId: hook.id,
				nodeType: "event",
				eventIndex: i,
				raw: event,
			},
		});
	}

	currentX += X_SPACING;
	previousNodeIds.push(...eventIds);

	if (hook.conditions && hook.conditions.length > 0) {
		const conditionIds: string[] = [];
		for (const [i, condition] of hook.conditions.entries()) {
			const id = `hook-${hook.id}-condition-${i}`;
			conditionIds.push(id);
			nodes.push({
				id,
				type: "condition",
				position: { x: currentX, y: startY + i * Y_SPACING },
				data: {
					label: condition.type,
					description: condition.pattern || condition.expression || condition.filePath || `Condition ${i + 1}`,
					hookId: hook.id,
					nodeType: "condition",
					conditionIndex: i,
					raw: condition,
				},
			});

			for (const prevId of previousNodeIds) {
				edges.push({ id: `edge-${prevId}-${id}`, source: prevId, target: id });
			}
		}
		currentX += X_SPACING;
		previousNodeIds.length = 0;
		previousNodeIds.push(...conditionIds);
	}

	if (hook.schedule && hook.schedule.type !== "immediate") {
		const id = `hook-${hook.id}-schedule`;
		nodes.push({
			id,
			type: "schedule",
			position: { x: currentX, y: startY },
			data: {
				label: hook.schedule.type,
				description: hook.schedule.type === "delayed" ? `${hook.schedule.delayMs}ms` : hook.schedule.cronExpression,
				hookId: hook.id,
				nodeType: "schedule",
				raw: hook.schedule,
			},
		});

		for (const prevId of previousNodeIds) {
			edges.push({ id: `edge-${prevId}-${id}`, source: prevId, target: id });
		}
		currentX += X_SPACING;
		previousNodeIds.length = 0;
		previousNodeIds.push(id);
	}

	const actionId = `hook-${hook.id}-action`;
	nodes.push({
		id: actionId,
		type: "action",
		position: { x: currentX, y: startY },
		data: {
			label: hook.action.type,
			description: hook.name,
			status: hook.enabled ? "active" : "draft",
			hookId: hook.id,
			nodeType: "action",
			raw: hook.action,
		},
	});

	for (const prevId of previousNodeIds) {
		edges.push({ id: `edge-${prevId}-${actionId}`, source: prevId, target: actionId });
	}
}

export function mapHooksToGraph(hooks: Hook[]): { nodes: Node[]; edges: Edge[] } {
	const nodes: Node[] = [];
	const edges: Edge[] = [];

	for (const [hookIndex, hook] of hooks.entries()) {
		processHook(hook, hookIndex, nodes, edges);
	}

	return { nodes, edges };
}
EOF

