				description: `Event source for ${hook.name}`,
				hookId: hook.id,
				nodeType: "event",
				eventIndex: i,
				raw: event,
			},
		});
	}
}

function processConditions(hook: Hook, startY: number, currentX: number, nodes: Node[], edges: Edge[], previousNodeIds: string[]) {
	if (!hook.conditions || hook.conditions.length === 0) return;

	const conditionIds: string[] = [];
	for (const [i, condition] of hook.conditions.entries()) {
		const id = `hook-${hook.id}-condition-${i}`;
		conditionIds.push(id);
		nodes.push({
			id,
			type: "condition",
			position: { x: currentX, y: startY + i * Y_SPACING },
			data: {
				label: condition.type,
				description: condition.pattern || condition.expression || condition.filePath || `Condition ${i + 1}`,
				hookId: hook.id,
				nodeType: "condition",
				conditionIndex: i,
				raw: condition,
			},
		});
		connectEdges(edges, previousNodeIds, id);
	}
	previousNodeIds.length = 0;
	previousNodeIds.push(...conditionIds);
}

function processSchedule(hook: Hook, startY: number, currentX: number, nodes: Node[], edges: Edge[], previousNodeIds: string[]) {
	if (!hook.schedule || hook.schedule.type === "immediate") return;

	const id = `hook-${hook.id}-schedule`;
	nodes.push({
