	processEvents(hook, startY, currentX, nodes, previousNodeIds);
	currentX += X_SPACING;

	processConditions(hook, startY, currentX, nodes, edges, previousNodeIds);
	if (hook.conditions && hook.conditions.length > 0) {
		currentX += X_SPACING;
	}

	processSchedule(hook, startY, currentX, nodes, edges, previousNodeIds);
	if (hook.schedule && hook.schedule.type !== "immediate") {
		currentX += X_SPACING;
	}

	const actionId = `hook-${hook.id}-action`;
	nodes.push({
		id: actionId,
		type: "action",
		position: { x: currentX, y: startY },
		data: {
			label: hook.action.type,
			description: hook.name,
			status: hook.enabled ? "active" : "draft",
			hookId: hook.id,
			nodeType: "action",
			raw: hook.action,
		},
	});
	connectEdges(edges, previousNodeIds, actionId);
}

export function mapHooksToGraph(hooks: Hook[]): {
	nodes: Node[];
	edges: Edge[];
} {
	const nodes: Node[] = [];
	const edges: Edge[] = [];

	for (const [hookIndex, hook] of hooks.entries()) {
		processHook(hook, hookIndex, nodes, edges);
	}

	return { nodes, edges };
}
